#!/usr/bin/env node
/*
 * Concatenates each page's scripts into one bundle, in the order the page
 * loaded them. Eight requests to GitHub Pages become one, and the ordering
 * contract the pages rely on (data -> render -> page bootstrap -> site.js,
 * which then drains __D2U_INIT) is preserved by construction.
 *
 * Not minified on purpose: the files are small, they gzip well, and a reader
 * comparing the live site against the repo should see the same code.
 */
const fs = require('fs');

const COMMON_HEAD = ['data-core', 'data-extra', 'data-media'];
const PAGES = {
  'index':        [...COMMON_HEAD, 'data-phase2', 'data-sites', 'render', 'page-index'],
  'mission':      [...COMMON_HEAD, 'data-sites', 'render', 'page-mission'],
  'programs':     [...COMMON_HEAD, 'render', 'page-programs'],
  'impact':       [...COMMON_HEAD, 'data-phase2', 'data-sites', 'render', 'page-impact'],
  'events':       [...COMMON_HEAD, 'data-sites', 'data-events', 'render', 'page-events'],
  'past-events':  [...COMMON_HEAD, 'data-sites', 'data-events', 'render', 'page-past-events'],
  'get-involved': [...COMMON_HEAD, 'data-phase2', 'data-sites', 'render', 'page-get-involved'],
  'donate':       [...COMMON_HEAD, 'data-donate', 'render', 'page-donate'],
  'blog':         [...COMMON_HEAD, 'data-sites', 'render', 'page-blog'],
  'rico-rich':    [...COMMON_HEAD, 'data-sites', 'render', 'page-rico-rich'],
};

/*
 * Guard: a bare 'assets/...' string literal is repo-relative, so inside a
 * WordPress page at /events-2026/ it resolves to /events-2026/assets/... and
 * 404s. That is exactly how the home page lost its hero video. Asset paths must
 * go through D2U_BASE, D2U_FIX or one of the data maps.
 */
// Legitimate uses are concatenated onto a base (D2U_BASE + 'assets/deck/'),
// so only flag a literal that is not preceded by one.
const BARE = /(?<!D2U_(?:BASE|FIX)\s*\+\s*)(['"])assets\/[^'"]*\1/g;
let violations = 0;
for (const f of fs.readdirSync('assets').filter(f => f.endsWith('.js') && !f.startsWith('bundle-'))) {
  const src = fs.readFileSync(`assets/${f}`, 'utf8')
    .replace(/\/\*[\s\S]*?\*\//g, '')          // strip block comments
    .replace(/(^|[^:])\/\/.*$/gm, '$1');        // strip line comments
  for (const m of src.matchAll(BARE)) {
    console.error(`  BARE ASSET PATH  assets/${f}: ${m[0]}`);
    violations++;
  }
}
if (violations) {
  console.error(`\n${violations} repo-relative asset path(s) would 404 on WordPress. Aborting.`);
  process.exit(1);
}

for (const [page, parts] of Object.entries(PAGES)) {
  const files = [...parts, 'site'];                     // site.js always last
  const body = files.map(f => {
    const src = fs.readFileSync(`assets/${f}.js`, 'utf8');
    return `/* ===== ${f}.js ===== */\n${src}`;
  }).join('\n');

  const out = `/* GENERATED by build-bundles.js — do not edit by hand.\n` +
              `   Page: ${page}. Source order: ${files.join(' -> ')} */\n${body}\n`;
  const dest = `assets/bundle-${page}.js`;
  fs.writeFileSync(dest, out);

  try { new Function(out); }
  catch (e) { console.error(`${dest}  SYNTAX ERROR: ${e.message}`); process.exitCode = 1; continue; }
  console.log(`${dest.padEnd(34)} ${String(out.length).padStart(7)}b  (${files.length} files)`);
}
